+///|
+async fn recover_diagnostic_health(directory : String) -> Unit {
+  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
+    return
+  }
+  let path = directory + "/diagnostic-health.json"
+  if !@fs.exists(path) {
+    return
+  }
+  let previous = @async.with_timeout(20, async fn() {
+    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
+      @fs.file_size(path) <= 65536L else {
+      return Json::null()
+    }
+    @json.parse(@fs.read_file(path).text())
+  }) catch {
+    error =>
+      if @async.is_being_cancelled() {
+        raise error
+      } else {
+        Json::null()
+      }
+  }
+  if field(previous, "priorLoss") is Some(Json::Array(losses)) {
+    for loss in losses {
+      if diagnostic_previous_losses.length() >= 31 {
+        break
+      }
+      diagnostic_previous_losses.push(diagnostic_previous_loss(loss))
+    }
+    if losses.length() > 31 {
+      diagnostic_previous_losses.push(diagnostic_previous_loss(Json::null()))
+    }
+  }
+  diagnostic_previous_losses.push(diagnostic_previous_loss(previous))
+  for event in diagnostic_previous_losses {
+    diagnostic_pending.push({ event, failed: true, time: @env.now(), })
+  }
+  diagnostic_recording_health.incident = true
+  diagnostic_recording_health.reason = "previous_run_unflushed"
+  diagnostic_recording_health.phase = "recovery"
+}
