fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  protected_secrets : Array[String],
  truncated : Ref[Bool],
  depth : Int32,
  stable_activity~ : Bool = false,
  secret_states~ : Bool = false,
  stable_operation~ : Bool = false,
  stable_arguments~ : Bool = false,
  parent~ : String = "",
) -> Json {
  let protected_secrets = if depth == 0 {
    let found : DiagnosticStructuredSecrets = {
      values: [],
      visited: 0,
      incomplete: false,
    }
    diagnostic_structured_secrets(value, found)
    if found.incomplete {
      truncated.val = true
      return { "reason": "protected_value_limit", "detailsTruncated": true }
    }
    protected_secrets + found.values
  } else {
    protected_secrets
  }
  if depth >= 64 {
    truncated.val = true
    return Json::string("[nested evidence omitted]")
  }
  match value {
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        let safe_name = if (
            stable_arguments &&
            [
              "arguments", "value", "source", "argumentCount", "reason", "command",
              "home", "context", "state", "effectiveContext",
            ].contains(name)
          ) ||
          (
            stable_operation &&
            (
              (
                depth == 0 &&
                [
                  "operationId", "workspaceId", "invocation", "backend", "phaseObservation",
                ].contains(name)
              ) ||
              (
                depth == 1 &&
                [
                  "command", "resolvedProgram", "lookupPath", "workingDirectory",
                  "sshAuthSock",
                ].contains(name)
              ) ||
              (
                parent == "backend" &&
                [
                  "kind", "phase", "state", "pipeline", "operationId", "step", "durationMs",
                  "error",
                ].contains(name)
              ) ||
              (parent == "phaseObservation" && name == "reason")
            )
          ) ||
          (
            stable_activity &&
            [
              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
              "workspaceId", "source", "code", "id", "uid", "context", "provider",
              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
              "error", "autoStop", "orcaVersion", "handle", "connected", "foregroundProcess",
              "hasChildProcesses", "processEvidence", "verdict", "capturedAgeMs",
              "ptyIncarnationId", "observationEpoch", "stateStartedAt", "updatedAt",
              "working", "queuedMessages", "actionablePrompts", "backgroundTasks",
            ].contains(name)
          ) {
          name
        } else {
          diagnostic_text(name, environment~, protected_secrets~)
        }
        if field(result, safe_name) is Some(_) {
          truncated.val = true
          continue
        }
        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
          truncated.val = true
        }
        set_field(
          result,
          safe_name,
          if credential_field(name, for_diagnostics=true) ||
            key == "pairingcode" {
            if secret_states &&
              field(item, "state") is Some(Json::String(state)) &&
              ["unset", "empty", "set"].contains(state) {
              let masked : Json = { "state": state }
              if field(item, "value") is Some(_) {
                set_field(masked, "value", Json::string("[redacted]"))
              }
              if field(item, "truncated") == Some(Json::boolean(true)) {
                set_field(masked, "truncated", Json::boolean(true))
                truncated.val = true
              }
              masked
            } else {
              Json::string("[redacted]")
            }
          } else if stable_activity &&
            name == "activity" &&
            (
              item == Json::string("idle") ||
              item == Json::string("active") ||
              item == Json::string("unknown")
            ) {
            item
          } else if stable_activity &&
            parent == "agent" &&
            item is Json::String(text) &&
            (
              (
                name == "state" &&
                ["working", "waiting", "blocked", "monitoring", "done"].contains(
                  text,
                )
              ) ||
              (
                name == "programState" &&
                ["working", "blocked", "idle"].contains(text)
              )
            ) {
            item
          } else {
            diagnostic_json(
              item,
              environment,
              protected_secrets,
              truncated,
              depth + 1,
              stable_activity~,
              secret_states~,
              stable_operation~,
              stable_arguments~,
              parent=name,
            )
          },
        )
      }
      result
    }
    Json::Array(values) =>
      Json::array(
        values.map(item => {
          diagnostic_json(
            item,
            environment,
            protected_secrets,
            truncated,
            depth + 1,
            stable_activity~,
            secret_states~,
            stable_operation~,
            stable_arguments~,
            parent~,
          )
        }),
      )
    Json::String(text) => {
      let safe = diagnostic_text(text, environment~, protected_secrets~)
      if safe.has_suffix("\n[error details incomplete or truncated]") {
        truncated.val = true
      }
      Json::string(safe)
    }
    Json::Number(_, ..) if protected_secrets.contains(value.stringify()) =>
      Json::string("[redacted]")
    _ => value
  }
}

///|
async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
  let length = if size > 262144L { 262144 } else { size.to_int() }
  let bytes = FixedArray::make(length, b'\x00')
  let read = file.read_at(bytes, position=size - length.to_int64())
  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
  let lines = text.split("\n").to_array()
  let kept = FixedArray::make(lines.length(), false)
  let mut remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if i == 0 && size > length.to_int64() {
      continue
    }
    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
    let overhead = if field(event, "runId") is Some(Json::String(_)) {
      100
    } else {
      0
    }
    let length = lines[i].length() + 1 + overhead
    if length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if kept[i] || (i == 0 && size > length.to_int64()) {
      continue
    }
    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
    let failed = field(event, "errorType") is Some(_) ||
      (match field(event, "status") {
        Some(Json::String(status)) =>
          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
            status,
          )
        _ => false
      })
    let overhead = if field(event, "runId") is Some(Json::String(_)) {
      100
    } else {
      0
    }
    let length = lines[i].length() + 1 + overhead
    if failed && length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  let dropped_runs : Map[String, Bool] = Map([])
  for i in 0..<(lines.length() - 1) {
    if !kept[i] {
      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
      if field(event, "runId") is Some(Json::String(id)) {
        dropped_runs.set(id, true)
      }
    }
  }
  let result = @buffer.Buffer(size_hint=131072)
  for i in 0..<lines.length() {
    if kept[i] {
      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
      if field(event, "runId") is Some(Json::String(id)) {
        set_field(
          event,
          "runCompleteness",
          Json::string(
            if dropped_runs.contains(id) ||
              field(event, "runCompleteness") == Some(Json::string("partial")) {
              "partial"
            } else {
              "unknown"
            },
          ),
        )
        set_field(event, "runMissingReason", Json::string("retention_limit"))
        result.write_string_utf8(event.stringify() + "\n")
      } else {
        result.write_string_utf8(lines[i].to_owned() + "\n")
      }
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

///|
fn diagnostic_current_run_count(text : String) -> Int32 {
  let mut count = 0
  for line in text.split("\n") {
    let event = @json.parse(line.to_owned()) catch { _ => Json::null() }
    if field(event, "runId") == Some(Json::string(recording_run_id)) {
      count += 1
    }
  }
  count
}

