async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
  let length = if size > 262144L { 262144 } else { size.to_int() }
  let bytes = FixedArray::make(length, b'\x00')
  let read = file.read_at(bytes, position=size - length.to_int64())
  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
  let lines = text.split("\n").to_array()
  let kept = FixedArray::make(lines.length(), false)
  let mut remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if i == 0 && size > length.to_int64() {
      continue
    }
    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
    let overhead = if field(event, "runId") is Some(Json::String(_)) {
      100
    } else {
      0
    }
    let length = lines[i].length() + 1 + overhead
    if length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if kept[i] || (i == 0 && size > length.to_int64()) {
      continue
    }
    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
    let failed = field(event, "errorType") is Some(_) ||
      (match field(event, "status") {
        Some(Json::String(status)) =>
          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
            status,
          )
        _ => false
      })
    let overhead = if field(event, "runId") is Some(Json::String(_)) {
      100
    } else {
      0
    }
    let length = lines[i].length() + 1 + overhead
    if failed && length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  let dropped_runs : Map[String, Bool] = Map([])
  for i in 0..<(lines.length() - 1) {
    if !kept[i] {
      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
      if field(event, "runId") is Some(Json::String(id)) {
        dropped_runs.set(id, true)
      }
    }
  }
  let result = @buffer.Buffer(size_hint=131072)
  for i in 0..<lines.length() {
    if kept[i] {
      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
      if field(event, "runId") is Some(Json::String(id)) {
        set_field(
          event,
          "runCompleteness",
          Json::string(
            if dropped_runs.contains(id) ||
              field(event, "runCompleteness") == Some(Json::string("partial")) {
              "partial"
            } else {
              "unknown"
            },
          ),
        )
        set_field(event, "runMissingReason", Json::string("retention_limit"))
        result.write_string_utf8(event.stringify() + "\n")
      } else {
        result.write_string_utf8(lines[i].to_owned() + "\n")
      }
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

