fn diagnostic_current_run_count(text : String) -> Int32 {
  let mut count = 0
  for line in text.split("\n") {
    let event = @json.parse(line.to_owned()) catch { _ => Json::null() }
    if field(event, "runId") == Some(Json::string(recording_run_id)) {
      count += 1
    }
  }
  count
}

