  value : String,
  output : String,
  uncertain : Bool,
  destination : Array[String],
  result : DiagnosticProtectedValues,
) -> Unit {
  if value == "" ||
    (
      redact_known_values(output, [value]) == output &&
      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
    ) {
    return
  }
  if result.secrets.length() >= 512 {
    result.incomplete = true
    return
  }
  destination.push(value)
}

///|
fn diagnostic_protected_values(
  value : Json,
  result : DiagnosticProtectedValues,
  output : String,
  uncertain : Bool,
  secret~ : Bool = false,
  depth~ : Int32 = 0,
) -> Unit {
  if result.visited >= 65536 || depth >= 64 {
    result.incomplete = true
    return
  }
  result.visited += 1
  match value {
    Json::Number(_, ..) if secret =>
      diagnostic_add_protected(
        value.stringify(),
        output,
        uncertain,
        result.secrets,
        result,
      )
    Json::String(text) if text != "" && secret => {
      let destination = result.secrets
      diagnostic_add_protected(text, output, uncertain, destination, result)
      for line in text.replace_all(old="\r", new="\n").split("\n") {
        if line != "" && line.length() < text.length() {
          diagnostic_add_protected(
            line.to_owned(),
            output,
            uncertain,
            destination,
            result,
          )
        }
        for word in line.split(" ") {
          for part in word.split("=") {
            if part != "" && part.length() < text.length() {
              diagnostic_add_protected(
                part.to_owned(),
                output,
                uncertain,
                destination,
                result,
              )
            }
          }
        }
      }
      let escaped = Json::string(text).stringify()
      if escaped.length() > 2 {
        let encoded = escaped[1:escaped.length() - 1].to_owned()
        if encoded != text {
          diagnostic_add_protected(
            encoded, output, uncertain, destination, result,
          )
        }
      }
    }
    Json::String(text) if text != "" => {
      let mut next_secret = false
      for word in text.split(" ") {
        let word = word.to_owned()
        if next_secret {
          diagnostic_add_protected(
            word,
            output,
            uncertain,
            result.secrets,
            result,
          )
          next_secret = false
        } else if word.split_once("=") is Some((name, value)) {
          if credential_field(name.to_owned(), for_diagnostics=true) {
            diagnostic_add_protected(
              value.to_owned(),
              output,
              uncertain,
              result.secrets,
              result,
            )
          }
        } else if word.has_prefix("-") &&
          credential_field(word, for_diagnostics=true) {
          next_secret = true
        }
      }
    }
    Json::Array(values) =>
      for item in values {
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret~,
          depth=depth + 1,
        )
      }
    Json::Object(values) =>
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret=secret ||
            credential_field(name, for_diagnostics=true) ||
            key == "pairingcode",
          depth=depth + 1,
        )
      }
    _ => ()
  }
}

///|
fn diagnostic_output(
  output : Bytes,
  environment : Map[String, String],
  protected_input? : String,
  protect_all_input~ : Bool = false,
  protected_secrets? : Array[String],
  omitted~ : Bool = false,
) -> String? {
  if output.length() == 0 {
    return if omitted {
      Some("[error details incomplete or truncated]")
    } else {
      None
    }
  }
  let limit = if output.length() > 8192 { 8192 } else { output.length() }
  let incomplete = omitted || limit < output.length()
  let text = @utf8.decode_lossy(output[:limit])
  let safeguards : DiagnosticProtectedValues = {
    secrets: [],
    visited: 0,
    incomplete: false,
  }
  if protected_input is Some(input) {
    diagnostic_protected_values(
      @json.parse(input),
      safeguards,
      text,
      incomplete,
      secret=protect_all_input,
    ) catch {
      _ => safeguards.incomplete = true
    }
  }
  let structured : DiagnosticStructuredSecrets = {
    values: [],
    visited: 0,
    incomplete: false,
  }
  for line in text.split("\n") {
    let parsed = @json.parse(line.to_owned()) catch { _ => Json::null() }
    diagnostic_structured_secrets(parsed, structured)
  }
  if structured.incomplete {
    safeguards.incomplete = true
  }
  if safeguards.incomplete {
    return Some(
      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
    )
  }
  Some(
    diagnostic_text(
      text,
      environment~,
      omitted=incomplete,
      protected_secrets=safeguards.secrets +
        structured.values +
        protected_secrets.unwrap_or([]),
      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
    ),
  )
}

///|
fn incomplete_diagnostic_detail(detail : String?) -> String {
  let detail = detail.unwrap_or("")
  if detail.contains("[error details incomplete or truncated]") {
    detail
  } else {
    detail +
    (if detail == "" { "" } else { "\n" }) +
    "[error details incomplete or truncated]"
  }
}

///|
priv struct DiagnosticCapture {
  output : @buffer.Buffer
  limit : Int32
  mut truncated : Bool
  mut finished : Bool
}

///|
fn DiagnosticCapture::new(limit : Int32) -> DiagnosticCapture {
  {
    output: @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 }),
    limit,
    truncated: false,
    finished: false,
  }
}

///|
async fn DiagnosticCapture::read(
  self : DiagnosticCapture,
  reader : @process.ReadFromProcess,
) -> Unit {
  try {
    while reader.read_some(max_len=4096) is Some(chunk) {
      let remaining = self.limit - self.output.length()
      let count = if chunk.length() < remaining {
        chunk.length()
      } else {
        remaining
      }
      if count > 0 {
        self.output.write_bytes(chunk[:count])
      }
      if count < chunk.length() {
        self.truncated = true
      }
    }
  } catch {
    error =>
      if @async.is_being_cancelled() {
        raise error
      } else {
        self.truncated = true
      }
  }
  self.finished = true
}

///|
async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
  @async.with_timeout(250, async fn() {
    while captures.iter().any(capture => !capture.finished) {
      @async.sleep(5)
    }
  }) catch {
    error => if @async.is_being_cancelled() { raise error }
  }
}

///|
async fn diagnostic_process_output(
  program : String,
  args : Array[String],
  environment~ : Map[String, String],
  cwd? : StringView,
  stdin? : &@process.ProcessInput,
  stdout_limit~ : Int32,
  stderr_limit~ : Int32,
  stderr_capture? : DiagnosticCapture,
) -> (Int32, Bytes, Bool, Bytes, Bool) {
  let (out, stdout) = @process.read_from_process()
  defer out.close()
  let (err, stderr) = @process.read_from_process()
  defer err.close()
  @async.with_task_group(async fn(group) {
    let child = @process.spawn(
      group,
      program,
      args,
      extra_env=environment,
      inherit_env=false,
      cwd?,
      stdin?,
      stdout~,
      stderr~,
    )
    let output = DiagnosticCapture::new(stdout_limit)
    let errors = stderr_capture.unwrap_or(DiagnosticCapture::new(stderr_limit))
    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
    let status = child.wait()
    if status == 0 {
      while !output.finished {
        @async.sleep(5)
      }
      wait_diagnostic_captures([errors])
    } else {
      wait_diagnostic_captures([output, errors])
    }
    (
      status,
      output.output.to_bytes(),
      output.truncated || !output.finished,
      errors.output.to_bytes(),
      errors.truncated || !errors.finished,
    )
  })
}

///|
async fn save_command_failure(
  stage : String,
  error : Error,
  recording? : Bool,
  phase? : String,
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  let cancelled = @async.is_being_cancelled()
  let timeout = error is @async.TimeoutError
  save_diagnostic(
    stage,
    if cancelled {
      "cancelled"
    } else if timeout {
      "timeout"
    } else {
      "failed"
    },
    error_type=if cancelled {
      "cancelled"
    } else if timeout {
      "timeout"
    } else if error is InvalidConfig(_) {
      "invalid_config"
    } else if error is AdapterError(_) {
      "adapter_error"
    } else if error is @os_error.OSError(_, ..) {
      "os_error"
    } else {
      "unexpected_error"
    },
    os_errno?=match error {
      @os_error.OSError(code, ..) => Some(code)
      _ => None
    },
    phase?,
    error_message=diagnostic_error(error),
    recording?,
  )
}

///|
fn process_error_type(output : String) -> String {
  let text = output.to_lower()
  if text.contains("out of memory") || text.contains("cannot allocate memory") {
    "memory_exhausted"
  } else if text.contains("no space left on device") {
    "disk_exhausted"
  } else if text.contains("address already in use") ||
    text.contains("addrinuse") {
    "address_in_use"
  } else if text.contains("permission denied (publickey") ||
    text.contains("authentication failed") {
    "authentication_failed"
  } else if text.contains("host key verification failed") {
    "host_key_failed"
  } else if text.contains("connection refused") {
    "connection_refused"
  } else if text.contains("connection timed out") ||
    text.contains("operation timed out") {
    "connection_timeout"
  } else if text.contains("could not resolve hostname") {
    "name_resolution"
  } else if text.contains("controlsocket") || text.contains("control socket") {
    "control_socket"
  } else if text.contains("build_vm:") {
    "vm_boot"
  } else if text.contains("create microsandbox vm") && text.contains("network:") {
    "vm_network"
  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
    "vm_mount"
  } else if text.contains("ensure microsandbox final image") ||
    text.contains("prepare microsandbox final image") {
    "vm_image"
  } else if text.contains("create microsandbox vm") {
    "vm_create"
  } else if text.contains("start microsandbox vm") {
    "vm_start"
  } else if text.contains("no such file or directory") ||
    text.contains("not found") {
    "missing_resource"
  } else if text.contains("permission denied") {
    "permission_denied"
  } else if text.contains("database is locked") ||
    text.contains("database locked") {
    "database_locked"
  } else if text.contains("too many open files") {
    "file_limit"
  } else {
    "process_exit"
  }
}

