  value : Json,
  result : DiagnosticProtectedValues,
  output : String,
  uncertain : Bool,
  secret~ : Bool = false,
  depth~ : Int32 = 0,
) -> Unit {
  if result.visited >= 65536 || depth >= 64 {
    result.incomplete = true
    return
  }
  result.visited += 1
  match value {
    Json::Number(_, ..) if secret =>
      diagnostic_add_protected(
        value.stringify(),
        output,
        uncertain,
        result.secrets,
        result,
      )
    Json::String(text) if text != "" && secret => {
      let destination = result.secrets
      diagnostic_add_protected(text, output, uncertain, destination, result)
      for line in text.replace_all(old="\r", new="\n").split("\n") {
        if line != "" && line.length() < text.length() {
          diagnostic_add_protected(
            line.to_owned(),
            output,
            uncertain,
            destination,
            result,
          )
        }
        for word in line.split(" ") {
          for part in word.split("=") {
            if part != "" && part.length() < text.length() {
              diagnostic_add_protected(
                part.to_owned(),
                output,
                uncertain,
                destination,
                result,
              )
            }
          }
        }
      }
      let escaped = Json::string(text).stringify()
      if escaped.length() > 2 {
        let encoded = escaped[1:escaped.length() - 1].to_owned()
        if encoded != text {
          diagnostic_add_protected(
            encoded, output, uncertain, destination, result,
          )
        }
      }
    }
    Json::String(text) if text != "" => {
      let mut next_secret = false
      for word in text.split(" ") {
        let word = word.to_owned()
        if next_secret {
          diagnostic_add_protected(
            word,
            output,
            uncertain,
            result.secrets,
            result,
          )
          next_secret = false
        } else if word.split_once("=") is Some((name, value)) {
          if credential_field(name.to_owned(), for_diagnostics=true) {
            diagnostic_add_protected(
              value.to_owned(),
              output,
              uncertain,
              result.secrets,
              result,
            )
          }
        } else if word.has_prefix("-") &&
          credential_field(word, for_diagnostics=true) {
          next_secret = true
        }
      }
    }
    Json::Array(values) =>
      for item in values {
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret~,
          depth=depth + 1,
        )
      }
    Json::Object(values) =>
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret=secret ||
            credential_field(name, for_diagnostics=true) ||
            key == "pairingcode",
          depth=depth + 1,
        )
      }
    _ => ()
  }
}

