    #|# orca-relay-readiness
    #|set -eu
    #|curl --disable --noproxy '*' --silent --max-time 1 --max-filesize 4096 --write-out '\n%{http_code}' http://localhost:12049/ready
  let started = @env.now()
  let environment = workspace_environment(state)
  let pairing = if state_recording(state) {
    workspace_pairing_secrets(state)
  } else {
    Some([])
  }
  if pairing is None {
    suppress_workspace_recording(state)
  }
  let pairing_secrets = pairing.unwrap_or([])
  let evidence : Json = { "gitEnabled": git_enabled }
  let mut phase = "readiness"
  let mut exit_code = None
  let mut error_detail = None
  let mut cancelled = false
  let mut evidence_incomplete = false
  let mut stderr_capture = DiagnosticCapture::new(8192)
  let result = @async.with_timeout(3000, async fn() {
    let (code, output, output_truncated, stderr, stderr_truncated) = diagnostic_process_output(
      workspace_program(state, "ssh"),
      ssh_mux_options(state, directory) + [script],
      environment~,
      cwd?=workspace_directory(state).map(path => path[:]),
      stdout_limit=8192,
      stderr_limit=8192,
      stderr_capture~,
    )
    exit_code = Some(code)
    evidence_incomplete = output_truncated || stderr_truncated
    set_field(
      evidence,
      "readinessStderr",
      diagnostic_output(
        stderr,
        environment,
        protected_secrets=pairing_secrets,
        omitted=stderr_truncated,
      )
      .map(Json::string)
      .unwrap_or(Json::null()),
    )
    if code != 0 {
      error_detail = diagnostic_output(
        stderr,
        environment,
        protected_secrets=pairing_secrets,
        omitted=stderr_truncated,
      )
      if output_truncated {
        error_detail = Some(incomplete_diagnostic_detail(error_detail))
      }
      return RelayReadiness::Retry(
        if code == 28 {
          "http_timeout"
        } else {
          "transport_error"
        },
      )
    }
    if output_truncated {
      error_detail = Some(
        "Readiness response exceeds the capture limit\n[error details incomplete or truncated]",
      )
      return RelayReadiness::Retry("response_too_large")
    }
    let text = @utf8.decode(output).trim().to_owned()
    let lines = text.split("\n").to_array()
    let status = lines.last().unwrap_or("").to_owned()
    let body = if text.length() >= status.length() {
      text[:text.length() - status.length()].to_owned().trim().to_owned()
    } else {
      ""
    }
    let body_json = if body == "" {
      Json::null()
    } else {
      @json.parse(body) catch {
        _ => Json::string(body)
      }
    }
    set_field(evidence, "responseBody", body_json)
    if status.length() == 3 && status.iter().all(c => c >= '0' && c <= '9') {
      set_field(evidence, "httpStatus", Json::string(status))
    }
    if status == "404" {
      return RelayReadiness::Unsupported
    }
    if status != "200" {
      return RelayReadiness::Retry(
        if status == "503" {
          "http_503"
        } else {
          "http_error"
        },
      )
    }
    phase = "response"
    let value = @json.parse(body) catch {
      error => {
        error_detail = Some(diagnostic_error(error, environment~))
        return RelayReadiness::Retry("schema_invalid")
      }
    }
    let response_version : Json = match field(value, "version") {
      None => { "state": "missing" }
      Some(Json::Number(number, ..)) => { "state": "number", "value": number }
      Some(Json::String(_)) => { "state": "invalid_type", "type": "string" }
      Some(item) if item == Json::boolean(true) || item == Json::boolean(false) =>
        { "state": "invalid_type", "type": "boolean" }
      Some(Json::Null) => { "state": "invalid_type", "type": "null" }
      Some(Json::Array(_)) => { "state": "invalid_type", "type": "array" }
      Some(Json::Object(_)) => { "state": "invalid_type", "type": "object" }
