      let progress = Progress::new("relay-probe", environment~)
      for (name, source) in [("expectedOwner", state), ("observedOwner", value)] {
        let key = if name == "expectedOwner" { "user" } else { "owner" }
        if field(source, key) is Some(Json::String(owner)) {
