        cwd?=workspace_directory(state).map(path => path[:]),
        stdout_limit=0,
        stderr_limit=8192,
        stderr_capture~,
      )
      exit_code = Some(code)
      evidence_incomplete = evidence_incomplete ||
        output_truncated ||
        stderr_truncated
