        .map(Json::string)
        .unwrap_or(Json::null()),
      )
      if code == 1 {
        error_detail = diagnostic_output(
          stderr,
          environment,
          protected_secrets=pairing_secrets,
          omitted=stderr_truncated,
        )
        if output_truncated {
          error_detail = Some(incomplete_diagnostic_detail(error_detail))
        }
        return RelayReadiness::WaitingForGitHelper
      }
      if code != 0 {
        error_detail = diagnostic_output(
          stderr,
          environment,
          protected_secrets=pairing_secrets,
          omitted=stderr_truncated,
        )
        if output_truncated {
          error_detail = Some(incomplete_diagnostic_detail(error_detail))
        }
        return RelayReadiness::Retry("transport_error")
      }
    }
    RelayReadiness::Ready
  }) catch {
