///|
async test "subprocess capture drains excess output and marks diagnostic loss" {
  let environment : Map[String, String] = { "PATH": "/usr/bin:/bin" }
  let script =
    #|printf 'transport failure token=fixture-capture-secret\n' >&2
    #|awk 'BEGIN { for (i=0; i<20000; i++) printf "x" }'
    #|awk 'BEGIN { for (i=0; i<20000; i++) printf "y" }' >&2
    #|exit 9
  let (status, output, output_truncated, errors, errors_truncated) = diagnostic_process_output(
    "/bin/sh",
    ["-c", script],
    environment~,
    stdout_limit=32,
    stderr_limit=128,
  )
  assert_eq(status, 9)
  assert_eq(output.length(), 32)
  assert_true(output_truncated)
  assert_true(errors_truncated)
  let detail = diagnostic_output(errors, environment, omitted=errors_truncated).unwrap()
  assert_true(detail.contains("transport failure"), msg=detail)
  assert_false(detail.contains("fixture-capture-secret"), msg=detail)
  assert_true(
    detail.contains("[error details incomplete or truncated]"),
    msg=detail,
  )
}

///|
async test "subprocess capture bounds inherited pipe lifetime" {
  let (directory, environment) = fixture()
  defer cleanup_fixture(directory)
  defer {
    @fs.write_file(directory + "/release-pipes", "") catch {
      _ => ()
    }
    if @fs.exists(directory + "/pipe-descendant") {
      let pid = @string.parse_int(
        @fs.read_file(directory + "/pipe-descendant").text(),
      )
      @async.with_timeout(3000, async fn() {
        while process_start(pid) != 0 {
          @async.sleep(10)
        }
      }) catch {
        _ => ()
      }
    }
  }
  let script =
    #|(while test ! -f "$HOME/release-pipes"; do sleep 0.05; done) >/dev/null &
    #|printf '%s' "$!" > "$HOME/pipe-descendant"
    #|printf ready
  let (status, output, output_truncated, errors, errors_truncated) = @async.with_timeout(
    10000,
    async fn() {
      diagnostic_process_output(
        "/bin/sh",
        ["-c", script],
        environment~,
        stdout_limit=128,
        stderr_limit=128,
      )
    },
  )
  assert_eq(status, 0)
  assert_eq(@utf8.decode(output), "ready")
  assert_false(output_truncated)
  assert_true(errors_truncated)
  assert_true(
    diagnostic_output(errors, environment, omitted=errors_truncated)
    .unwrap()
    .contains("incomplete or truncated"),
  )
  @fs.write_file(directory + "/release-pipes", "")
  let pid = @string.parse_int(
