///|
fn unknown_activity(reason : String) -> Json {
  { "activity": "unknown", "reason": redact_credentials(reason) }
}

///|
async fn bulk_context(state : Json) -> String {
  let selection = @json.parse(state.stringify())
  if selection is Json::Object(fields) {
    fields.remove("context")
  }
  let contexts = @json.parse(
    devsy(
      selection,
      ["--result-format", "json", "context", "list"],
      "bulk-context",
    ),
  )
  guard contexts is Json::Array(items) else {
    raise AdapterError("Invalid context list")
  }
  let selected = items.filter(item => {
    field(item, "default") == Some(Json::boolean(true))
  })
  guard selected.length() == 1 else {
    raise AdapterError("No unique effective Devsy context")
  }
  required(selected[0], "name")
}

///|
async fn bulk_identity(state : Json, provider : String) -> (Bool, Bool) {
  let current = workspace(state)
  match current {
    None => (true, false)
    Some(value) => {
      let actual_provider = field(value, "provider").bind(p => field(p, "name"))
      let in_scope = actual_provider == Some(Json::string(provider)) &&
        field(value, "context")
        .map(c => c == field(state, "context").unwrap())
        .unwrap_or(true)
      if !in_scope {
        let secrets = saved_workspace_secrets(state)
        if secrets is None {
          suppress_workspace_recording(state)
        }
        save_diagnostic(
          "bulk-workspace",
          "excluded",
          evidence={
            "id": required(state, "workspaceId"),
            "context": required(state, "context"),
            "observedContext": field(value, "context").unwrap_or(Json::null()),
            "requestedProvider": provider,
            "observedProvider": actual_provider.unwrap_or(Json::null()),
            "reason": "outside_scope",
          },
          protected_secrets?=secrets,
          environment=workspace_environment(state),
          recording=state_recording(state) && secrets is Some(_),
        )
      }
      (
        in_scope,
        in_scope && field(value, "uid") == field(state, "workspaceUid"),
      )
    }
  }
}

///|
async fn bulk_one(mode : String, state : Json, options : BulkOptions) -> Json? {
  let id = required(state, "workspaceId")
  let saved_secrets = saved_workspace_secrets(state)
  let secrets = saved_secrets.unwrap_or([])
  if saved_secrets is None {
    suppress_workspace_recording(state)
  }
  let result : Json = {
    "id": id,
    "uid": required(state, "workspaceUid"),
    "context": required(state, "context"),
    "provider": options.provider,
    "identityVerified": false,
    "vmStatus": "unknown",
    "activity": "unknown",
    "outcome": "skipped",
  }
  let mut mutating = false
  try {
    set_field(result, "autoStop", idle_status(state))
    let effective_context = bulk_context(state)
    guard required(state, "context") == effective_context else {
      save_diagnostic(
        "bulk-workspace",
        "excluded",
        evidence={
          "id": id,
          "savedContext": required(state, "context"),
          "effectiveContext": effective_context,
          "reason": "context_mismatch",
        },
        protected_secrets=secrets,
        environment=workspace_environment(state),
        recording=operation_recording(state),
      )
      return None
    }
    let lock = connection_operation_lock(state, validate=false)
    defer lock.close()
    snapshot_workspace_recording(state, required(state, "tunnelDirectory"))
    match saved_workspace_secrets(state) {
      Some(values) =>
        for secret in values {
          secrets.push(secret)
        }
      None => suppress_workspace_recording(state)
    }
    validate_connection_owner(state)
    let (in_scope, matched) = bulk_identity(state, options.provider)
    guard in_scope else { return None }
    set_field(result, "identityVerified", Json::boolean(matched))
    guard matched else {
      set_field(
        result,
        "evidence",
        unknown_activity("workspace_missing_or_replaced"),
      )
      save_diagnostic(
        "bulk-workspace",
        "skipped",
        error_type="workspace_missing_or_replaced",
        evidence=result,
        protected_secrets=secrets,
        environment=workspace_environment(state),
        recording=operation_recording(state),
      )
      return Some(result)
    }
    let status = workspace_status(state)
    set_field(result, "vmStatus", Json::string(status))
    let activity_pairing : Ref[String?] = { val: None, }
    let evidence = if status != "Running" {
      unknown_activity("workspace_not_running")
    } else if options.force || mode == "resume" {
      unknown_activity(
        if options.force {
          "forced_without_activity_check"
        } else {
          "resume_does_not_require_activity"
        },
      )
    } else {
      observe_activity(state, pairing_out=activity_pairing) catch {
        error =>
          unknown_activity(
            if activity_pairing.val is Some(_) {
              diagnostic_error(error, environment=workspace_environment(state))
            } else {
              workspace_error_detail(state, error)
            },
          )
      }
    }
    set_field(result, "activity", field(evidence, "activity").unwrap())
    let evidence_incomplete : Ref[Bool] = { val: false, }
    let safe_evidence = if status != "Running" ||
      options.force ||
      mode == "resume" {
      evidence
    } else {
      match
        saved_workspace_secrets(
          state,
          for_output=true,
          include_pairing=activity_pairing.val is None,
        ) {
        Some(values) => {
          if activity_pairing.val is Some(pairing) && pairing != "" {
            add_protected_secret(values, pairing)
          }
          diagnostic_json(
            evidence,
            workspace_environment(state),
            values,
            evidence_incomplete,
            0,
            stable_activity=true,
          )
        }
        None => {
          evidence_incomplete.val = true
          (
            {
              "activity": field(evidence, "activity").unwrap(),
              "reason": "activity details unavailable",
              "detailsTruncated": true,
            } : Json)
        }
      }
    }
    set_field(result, "evidence", safe_evidence)
    if evidence_incomplete.val {
      set_field(result, "evidenceTruncated", Json::boolean(true))
    }
    save_diagnostic(
      "bulk-observation",
      mode,
      tunnel_directory=required(state, "tunnelDirectory"),
      evidence=result,
      evidence_incomplete=evidence_incomplete.val,
      evidence_stable_activity=true,
      protected_secrets=secrets,
      environment=workspace_environment(state),
      recording=operation_recording(state),
    )
    if mode == "status" {
      set_field(result, "outcome", Json::string("observed"))
      save_diagnostic(
        "bulk-workspace",
        "observed",
        evidence=result,
        evidence_incomplete=evidence_incomplete.val,
        evidence_stable_activity=true,
        protected_secrets=secrets,
        environment=workspace_environment(state),
        recording=operation_recording(state),
      )
      return Some(result)
    }
    if mode == "stop" {
      if status == "Stopped" {
        set_field(result, "reason", Json::string("already_stopped"))
      } else if !options.force &&
        (
          status != "Running" ||
          field(evidence, "activity") != Some(Json::string("idle"))
        ) {
        set_field(result, "reason", Json::string("not_idle"))
      } else {
        let (scope, valid) = bulk_identity(state, options.provider)
        guard scope && valid else {
          raise AdapterError("Workspace changed before stop")
        }
        mutating = true
        pause_tunnel(state)
        defer unpause_tunnel(state)
        stop_workspace(state)
        set_field(result, "outcome", Json::string("success"))
      }
    } else if status == "Running" {
      set_field(result, "reason", Json::string("already_running"))
    } else if status != "Stopped" {
      set_field(result, "reason", Json::string("workspace_not_stopped"))
    } else {
      let (scope, valid) = bulk_identity(state, options.provider)
      guard scope && valid else {
        raise AdapterError("Workspace changed before resume")
      }
      mutating = true
      unpause_tunnel(state)
      ignore(
        devsy(
          state,
          [
            "--result-format", "json", "workspace", "up", "--id", id, "--ide-launch",
            "skip",
          ] +
          orca_storage_args(state),
          "workspace-resume",
        ),
      )
      set_field(result, "outcome", Json::string("success"))
      idle_reset(state, "workspace_resumed")
    }
  } catch {
    error => {
      set_field(
        result,
        "outcome",
        Json::string(if mutating { "failed" } else { "skipped" }),
      )
      let detail = workspace_error_detail(state, error)
      set_field(result, "evidence", unknown_activity(detail))
      set_field(result, "error", Json::string(detail))
    }
  }
  if mode == "resume" &&
    field(result, "outcome") == Some(Json::string("success")) {
    recover_connection(state) catch {
      error => {
        set_field(result, "outcome", Json::string("failed"))
        set_field(
          result,
          "error",
          Json::string(workspace_error_detail(state, error)),
        )
      }
    }
  }
  save_diagnostic(
    "bulk-workspace",
    mode,
    evidence=result,
    evidence_incomplete=field(result, "evidenceTruncated") ==
      Some(Json::boolean(true)),
    evidence_stable_activity=true,
    protected_secrets=secrets,
    environment=workspace_environment(state),
    recording=operation_recording(state),
  )
  Some(result)
}

///|
pub async fn bulk(mode : String, args : Array[String]) -> Unit {
  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
  let mut failure_recorded = false
  let recording_allowed : Ref[Bool] = {
    val: @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
  }
  errdefer (if !failure_recorded && @async.is_being_cancelled() {
    @async.protect_from_cancel(async fn() {
      save_diagnostic(
        "bulk",
