///|
async test "successful Codex refresh records sanitized stderr" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.mkdir(directory + "/.codex")
  @fs.write_file(
    directory + "/.codex/auth.json",
    synthetic_auth(@env.now().to_double() / 1000 + 3600).stringify(),
  )
  @fs.write_file(
    directory + "/.codex/next-auth.json",
    synthetic_auth(@env.now().to_double() / 1000 + 1209600).stringify(),
  )
  fake_codex(directory)
  @fs.rename(directory + "/bin/codex", directory + "/bin/codex-original")
  let wrapper =
    #|#!/bin/sh
    #|printf 'refresh used a fallback fixture-refresh\n' >&2
    #|exec "$HOME/bin/codex-original" "$@"
  @fs.write_file(directory + "/bin/codex", wrapper + "\n", permission=0o700)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main, addons: {codexAuth: true}}\nenvironmentRecipes: [{id: test}]\n",
  )
  let (status, output, errors) = invoke("create", env, directory)
  assert_eq(status, 0, msg=errors)
  let payload : Json = {
    "schemaVersion": 1,
    "recipeResult": @json.parse(output),
  }
  defer ignore(invoke("destroy", env, directory, payload~))
  let events = fixture_events(directory)
  let warnings = events.filter(event => {
    field(event, "stage") == Some(Json::string("codex-refresh")) &&
    (
      field(event, "status") == Some(Json::string("warning")) ||
      field(event, "status") == Some(Json::string("stderr-incomplete"))
    )
  })
  assert_eq(warnings.length(), 1)
  assert_true(
    required(warnings[0], "errorMessage").contains("refresh used a fallback"),
  )
  assert_false(Json::array(events).stringify().contains("fixture-refresh"))
}

///|
async test "Codex refresh timeout retains captured stderr" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.mkdir(directory + "/.codex")
  @fs.write_file(
    directory + "/.codex/auth.json",
    synthetic_auth(@env.now().to_double() / 1000 + 3600).stringify(),
  )
  let codex =
    #|#!/bin/sh
    #|printf 'refresh transport stalled fixture-refresh\n' >&2
    #|exec sleep 60
  @fs.write_file(directory + "/bin/codex", codex + "\n", permission=0o700)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main, addons: {codexAuth: true}}\nenvironmentRecipes: [{id: test}]\n",
  )
  let (status, output, errors) = @async.with_timeout(90000, async fn() {
    invoke("create", env, directory)
  })
  assert_eq(status, 0, msg=errors)
  let payload : Json = {
    "schemaVersion": 1,
    "recipeResult": @json.parse(output),
  }
  defer ignore(invoke("destroy", env, directory, payload~))
  let events = fixture_events(directory)
  let cancelled = events.filter(event => {
    field(event, "stage") == Some(Json::string("codex-refresh")) &&
    field(event, "status") == Some(Json::string("cancelled"))
  })
  assert_eq(cancelled.length(), 1)
  assert_true(
    required(cancelled[0], "errorMessage").contains("refresh transport stalled"),
  )
  assert_eq(field(cancelled[0], "detailsTruncated"), Some(Json::boolean(true)))
  assert_false(Json::array(events).stringify().contains("fixture-refresh"))
  assert_true(
    events
    .iter()
    .any(event => {
      field(event, "stage") == Some(Json::string("codex-auth")) &&
      field(event, "errorType") == Some(Json::string("timeout"))
    }),
  )
}

