fn server_update_locked(
  script : String,
  inline_launch~ : Bool = false,
) -> String {
  let marker = "marker=\"$HOME/.local/share/orca-env-devsy/orca/update-active\"; mkdir \"$marker\" 2>/dev/null || { printf 'Another update may be running or its marker needs inspection\\n' >&2; exit 1; }; "
