    "mkdir \"$HOME/.local/share/orca-env-devsy/orca/update-active\" 2>/dev/null || { printf 'Another update may be running or its marker needs inspection\\n' >&2; exit 1; }; " +
    "trap 'rmdir \"$HOME/.local/share/orca-env-devsy/orca/update-active\"' EXIT; " +
    script
  } else {
    let body = "trap 'rmdir \"$HOME/.local/share/orca-env-devsy/orca/update-active\"' EXIT; sh -c " +
      quote(script)
    marker + "sh -c " + quote(body) + " & child=$!; wait \"$child\""
  }
}

