///|
async fn read_registration(socket : @socket.Tcp, limit : Int32) -> Json {
  let header = @buffer.Buffer()
  while true {
    let byte = socket.read_exactly(1)
    if byte == b"\n" {
      break
    }
    guard header.length() < 8 else {
      raise AdapterError("Invalid registration length")
    }
    header.write_bytes(byte)
  }
  let length = @string.parse_int(@utf8.decode(header.to_bytes()))
  guard length > 0 && length <= limit else {
    raise AdapterError("Registration is too large")
  }
  @json.parse(@utf8.decode(socket.read_exactly(length))) catch {
    _ => raise AdapterError("Invalid registration JSON")
  }
}

///|
async fn write_registration(socket : @socket.Tcp, value : Json) -> Unit {
  let bytes = @utf8.encode(value.stringify())
  guard bytes.length() <= 4194304 else {
    raise AdapterError("Registration is too large")
  }
  socket.write(bytes.length().to_string() + "\n")
  socket.write(bytes)
}

///|
async fn register_workspace(directory : String, environment? : Json) -> Unit {
  let values = match environment {
    Some(Json::Object(items)) => {
      let result : Map[String, String] = Map([])
      for (name, value) in items {
        if value is Json::String(text) {
          result.set(name, text)
        }
      }
      result
    }
    _ => @env.get_env_vars()
  }
  let recording = @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0") &&
    values.get("ORCA_ENV_DEVSY_RECORDING") != Some("0")
  diagnostic_operation_counter.val += 1
  let operation = recording_run_id +
    ":" +
    diagnostic_operation_counter.val.to_string()
  let context : Json = { "operationId": operation }
  let phase : Ref[String] = { val: "supervisor", }
  let mut last_phase = "supervisor"
  let mut attempts = 0
  let mut detail = "Supervisor registration endpoint is not ready"
  let started = @env.now()
  let diagnostic_directory = if recording {
    @fs.realpath(directory) catch {
      error => if @async.is_being_cancelled() { raise error } else { directory }
    }
  } else {
    directory
  }
  save_diagnostic(
    "workspace-registration",
    "started",
    tunnel_directory=diagnostic_directory,
    evidence=context,
    evidence_stable_operation=true,
    environment=values,
    recording~,
  )
  let failure = try {
    @async.with_timeout(10000, async fn() {
      while true {
        attempts += 1
        phase.val = "supervisor"
        set_field(context, "connectionId", Json::null())
        try {
          ensure_supervisor()
          register_workspace_inner(
            directory,
            operation,
            attempts,
            context,
            phase,
            recording,
            environment?,
          )
          return
        } catch {
          error => {
            if @async.is_being_cancelled() {
              raise error
            }
            last_phase = phase.val
            detail = diagnostic_error(error, environment=values)
            if attempts <= 3 {
              save_diagnostic(
                "workspace-registration",
                "retry",
                error_type="registration_retry",
                phase=last_phase,
                attempt=attempts,
                retry_delay_ms=100,
                error_message=detail,
                tunnel_directory=diagnostic_directory,
                evidence=context,
                evidence_stable_operation=true,
                environment=values,
                recording~,
              )
            }
          }
        }
        @async.sleep(100)
      }
    })
    None
  } catch {
    error => Some(error)
  }
  if failure is Some(error) {
    let cancelled = @async.is_being_cancelled()
    @async.protect_from_cancel(async fn() {
      save_diagnostic(
        "workspace-registration",
        if cancelled {
          "cancelled"
        } else if error is @async.TimeoutError {
          "timeout"
        } else {
          "failed"
        },
        error_type=if cancelled {
          "cancelled"
        } else if error is @async.TimeoutError {
          "registration_timeout"
        } else {
          "registration_failed"
        },
        phase=phase.val,
        attempt=attempts,
        timeout_ms=10000,
        duration_ms=(@env.now() - started).to_double(),
        error_message="Last attempt (" + last_phase + "): " + detail,
        tunnel_directory=diagnostic_directory,
        evidence=context,
        evidence_stable_operation=true,
        environment=values,
        recording~,
      )
    })
    if error is @async.TimeoutError {
      raise AdapterError(
        "Workspace registration timed out at " +
        phase.val +
        "; last attempt (" +
        last_phase +
        "): " +
        detail,
      )
    }
    raise error
  }
  save_diagnostic(
    "workspace-registration",
    "success",
    phase=phase.val,
    attempt=attempts,
    duration_ms=(@env.now() - started).to_double(),
    tunnel_directory=diagnostic_directory,
    evidence=context,
    evidence_stable_operation=true,
    environment=values,
    recording~,
  )
}

///|
async fn register_workspace_inner(
  directory : String,
  operation : String,
  attempt : Int32,
  context : Json,
  phase : Ref[String],
  recording : Bool,
  environment? : Json,
) -> Unit {
  phase.val = "descriptor"
  let path = adapter_state_home() + "/supervisor.json"
  let descriptor = @json.parse(@fs.read_file(path).text())
  let pid = @string.parse_int(required(descriptor, "pid"))
  let start = @string.parse_int64(required(descriptor, "start"))
  guard pid > 1 && start > 0 && process_start(pid) == start else {
    raise AdapterError("Supervisor registration endpoint is stale")
  }
  let port = @string.parse_int(required(descriptor, "port"))
  guard port > 0 && port <= 65535 else {
    raise AdapterError("Invalid supervisor port")
  }
  phase.val = "connect"
  let socket = @socket.Tcp::connect(
    @socket.Addr::parse("127.0.0.1:" + port.to_string()),
  )
  defer socket.close()
  phase.val = "peer"
  let peer = read_registration(socket, 4096)
  guard field(peer, "protocol") == Some(Json::number(1)) &&
    field(peer, "pid") == field(descriptor, "pid") &&
    field(peer, "start") == field(descriptor, "start") else {
    raise AdapterError("Supervisor registration endpoint changed")
  }
  if field(peer, "connectionId") is Some(Json::String(id)) &&
    registration_id_valid(id) {
    set_field(context, "connectionId", Json::string(id))
  }
  let environment = environment.unwrap_or_else(() => {
    let values = Json::empty_object()
    for (name, value) in @env.get_env_vars() {
      set_field(values, name, Json::string(value))
    }
    values
  })
  phase.val = "request"
  write_registration(socket, {
    "directory": directory,
    "environment": environment,
    "operationId": operation,
    "attempt": attempt,
    "recording": recording,
  })
  phase.val = "reply"
  let reply = read_registration(socket, 4096)
  guard field(reply, "accepted") == Some(Json::boolean(true)) else {
    raise AdapterError("Supervisor rejected workspace registration")
  }
  if field(field(reply, "diagnosticHealth").unwrap_or(Json::null()), "status") ==
    Some(Json::string("degraded")) {
    progress_write(
      "orca-env-devsy: warning: supervisor diagnostic recording is unavailable\n",
    )
  }
}

///|
fn registration_id_valid(id : String) -> Bool {
  id.length() > 0 &&
  id.length() <= 80 &&
  id.iter().all(c => (c >= '0' && c <= '9') || c == '_' || c == ':')
}

