        duration_ms=(@env.now() - started).to_double(),
        tunnel_directory=directory,
        evidence=context,
        evidence_stable_operation=true,
        environment~,
        recording~,
      )
    })
    None
  } catch {
    error => Some(error)
  }
  if failure is Some(error) {
    @async.protect_from_cancel(async fn() {
      save_diagnostic(
        "supervisor-registration",
        if error is @async.TimeoutError {
          "timeout"
        } else {
          "failed"
        },
        error_type=if error is @async.TimeoutError {
          "registration_timeout"
        } else {
          "registration_failed"
        },
        phase~,
        attempt?,
        timeout_ms=10000,
        duration_ms=(@env.now() - started).to_double(),
        error_message=diagnostic_error(error, environment?=workspace_env),
        tunnel_directory?=target,
        evidence=context,
        evidence_stable_operation=true,
        environment?=workspace_env,
        recording~,
      )
    })
    raise error
  }
}

