async test "Codex refresh records RPC cause without authentication tokens" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.mkdir(directory + "/.codex")
  let auth = synthetic_auth(@env.now().to_double() / 1000 + 3600)
  @fs.write_file(directory + "/.codex/auth.json", auth.stringify())
  let script =
    #|#!/bin/sh
    #|IFS= read -r initialize
    #|printf '{"id":1,"result":{}}\n'
    #|IFS= read -r initialized
    #|IFS= read -r request
    #|printf 'app-server refused token=fixture-refresh\n' >&2
    #|printf '{"id":2,"error":{"code":-32042,"message":"refresh denied token=fixture-refresh"}}\n'
  @fs.write_file(directory + "/bin/codex", script + "\n", permission=0o700)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main, addons: {codexAuth: true}}\nenvironmentRecipes: [{id: test}]\n",
  )
  let (status, output, errors) = invoke("create", env, directory)
  assert_eq(status, 0, msg=errors)
  let warnings = fixture_events(directory).filter(event => {
    field(event, "stage") == Some(Json::string("codex-refresh")) &&
    field(event, "status") == Some(Json::string("warning"))
  })
  assert_eq(warnings.length(), 1)
  let detail = required(warnings[0], "errorMessage")
  assert_true(detail.contains("-32042"), msg=detail)
  assert_true(detail.contains("refresh denied"), msg=detail)
  assert_false(detail.contains("fixture-refresh"))
  let records = @fs.read_file(
    directory + "/.local/state/orca-env-devsy/events.jsonl",
  ).text()
  assert_false(records.contains("fixture-refresh"))
  assert_false(errors.contains("fixture-refresh"))
  let payload : Json = {
    "schemaVersion": 1,
    "recipeResult": @json.parse(output),
  }
  let (destroyed, _, destroy_error) = invoke(
    "destroy",
    env,
    directory,
    payload~,
  )
  assert_eq(destroyed, 0, msg=destroy_error)
}
